using Microsoft.Xna.Framework;
namespace BluewaterHaul;
public sealed class TroubleState {
 public float Heat{get;set;}public float Escape{get;set;}public float ReportDelay{get;set;}public float LastX{get;set;}public float LastZ{get;set;}public int Fines{get;set;}public int Arrests{get;set;}public int Reports{get;set;}public string Incident{get;set;}="";public HashSet<int> Stolen{get;set;}=[];public Dictionary<long,float> PropertyDamage{get;set;}=[];
}
public sealed class PoliceUnit {public int Id;public Vector2 Point,Officer;public float Yaw,Repath;public List<Vector2> Route=[];public int Step;public bool OnFoot;}
public static class TroubleRules {
 public static int Stars(float heat)=>heat<=0?0:Math.Clamp((int)MathF.Ceiling(heat/30),1,3);
 public static float Damage(float speed)=>Math.Clamp((Math.Abs(speed)-2)*3,0,60);
 public static int Fine(string crime)=>crime=="Vehicle theft"?180:crime=="Dangerous driving"?90:60;
}
public sealed partial class SarniaGame {
 readonly List<PoliceUnit> police=[];float incidentCooldown,arrestTimer;bool troubleSeen;TroubleState Trouble=>state.Trouble;
 void InitializeTrouble(){police.Clear();for(int i=0;i<3;i++){var p=FindRoad(OutsidePosition+new Vector2(220+i*100,180-i*90));police.Add(new(){Id=i,Point=p,Officer=p});}arrestTimer=0;incidentCooldown=0;}
 bool LineOfSight(Vector2 a,Vector2 b){for(int i=1;i<16;i++){var p=Vector2.Lerp(a,b,i/16f);if(buildingGrid.TryGetValue(((int)MathF.Floor(p.X/128),(int)MathF.Floor(p.Y/128)),out var list)&&list.Any(w=>Geo.Contains(w.Points,p)))return false;}return true;}
 bool HasWitness(Vector2 point)=>citizens.Any(c=>Vector2.DistanceSquared(c.Point,point)<65*65&&LineOfSight(c.Point,point))||traffic.Any(t=>Vector2.DistanceSquared(t.Point,point)<80*80&&LineOfSight(t.Point,point));
 void Crime(string kind,Vector2 point,float severity){Trouble.Incident=kind;if(HasWitness(point)||police.Any(p=>Vector2.DistanceSquared(p.Point,point)<100*100&&LineOfSight(p.Point,point))){bool ongoing=Trouble.Heat>0;Trouble.Fines+=TroubleRules.Fine(kind);Trouble.LastX=point.X;Trouble.LastZ=point.Y;Trouble.Heat=Math.Clamp(Trouble.Heat+severity,0,90);if(!ongoing)Trouble.ReportDelay=3;Trouble.Escape=0;Trouble.Reports++;Tell(kind+" witnessed. Someone has called it in.");}else Tell(kind+" / no witness nearby. The repair bill remembers.");}
 TrafficAgent? NearStoppedTraffic()=>traffic.Where(t=>!t.Destroyed&&t.Speed<.8f&&Vector2.DistanceSquared(t.Point,position)<MathF.Pow(VehicleSpec.For(t.Kind).Length/2+2,2)).MinBy(t=>Vector2.DistanceSquared(t.Point,position));
 void TakeTraffic(TrafficAgent t){var v=new VehicleState{Id=1000+t.Id,Kind=t.Kind,Point=t.Point,Yaw=t.Yaw,Paint=t.Id,Damage=t.Damage,BurnTime=t.BurnTime,Destroyed=t.Destroyed};while(fleet.Any(w=>w.Id==v.Id))v.Id++;fleet.Add(v);VehicleTheft(v);traffic.Remove(t);EnterVehicle(v);}
 void VehicleTheft(VehicleState v){if(v.Id==0||Trouble.Stolen.Contains(v.Id))return;Trouble.Stolen.Add(v.Id);Crime("Vehicle theft",v.Point,32);}
 void Impact(Vector2 q,float heading,float velocity){if(Math.Abs(velocity)<3||incidentCooldown>0)return;incidentCooldown=2;float amount=TroubleRules.Damage(velocity);ActiveVehicle.Damage=Math.Clamp(ActiveVehicle.Damage+amount,0,100);var other=fleet.FirstOrDefault(v=>v.Id!=activeVehicle&&VehiclePhysics.Overlap(q,heading,ActiveSpec,v.Point,v.Yaw,VehicleSpec.For(v.Kind)));if(other!=null)other.Damage=Math.Clamp(other.Damage+amount,0,100);var building=world.Buildings.Where(b=>b.Enterable).MinBy(b=>Vector2.DistanceSquared(Geo.V(b.Center),q));if(building!=null&&Vector2.Distance(Geo.V(building.Center),q)<Math.Max(building.Box.Width,building.Box.Height)+12)Trouble.PropertyDamage[building.Id]=Math.Clamp(Trouble.PropertyDamage.GetValueOrDefault(building.Id)+amount,0,100);Crime(CitizenBlocked(q,heading,ActiveSpec)?"Dangerous driving":"Property damage",q,amount*.8f+8);}
 void Vandalize(){if(driving||interior!=0){Tell("Leave the vehicle to interact with street property.");return;}var(b,_,distance)=NearBuilding();if(b==null||distance>6){Tell("Walk beside a building, then X to damage its exterior.");return;}if(incidentCooldown>0)return;incidentCooldown=2;Trouble.PropertyDamage[b.Id]=Math.Clamp(Trouble.PropertyDamage.GetValueOrDefault(b.Id)+20,0,100);Crime("Property damage",position,22);}
 void Repair(){if(interior!=0)return;if(!world.Pois.Any(p=>p.Kind is "fuel" or "car_repair"&&Vector2.Distance(OutsidePosition,Geo.V(p.Point))<45)){Tell("K: repair near a mapped fuel station or repair shop.");return;}var v=driving?ActiveVehicle:NearVehicle();if(v==null){Tell("Bring the vehicle closer.");return;}int cost=(int)MathF.Ceiling(v.Damage*2);if(state.Money<cost){Tell("Repair costs $"+cost+". Not enough cash.");return;}state.Money-=cost;v.Damage=0;v.Destroyed=false;v.BurnTime=0;v.Fuel=Math.Max(v.Fuel,10);if(v.Id==0)state.Fuel=v.Fuel;Tell("Vehicle repaired for $"+cost+". Duct tape was not itemized.");}
 void SurrenderOrPay(){if(!police.Any(p=>Vector2.DistanceSquared(p.Point,OutsidePosition)<60*60)){Tell("B: approach a police unit to surrender or pay fines.");return;}if(Trouble.Heat>0){Arrest();return;}int paid=Math.Min(state.Money,Trouble.Fines);state.Money-=paid;Trouble.Fines-=paid;Tell("Paid $"+paid+" / outstanding fines $"+Trouble.Fines);}
 void Arrest(){int bill=Math.Max(60,Trouble.Fines);int paid=Math.Min(state.Money,bill);state.Money-=paid;Trouble.Fines=bill-paid;Trouble.Arrests++;Trouble.Heat=0;Trouble.Escape=Trouble.ReportDelay=0;arrestTimer=0;if(interior!=0)Leave();driving=false;speed=0;activeVehicle=0;position=FindRoad(new(-4930,1200));truck=FindRoad(position+new Vector2(25,0));state.TruckYaw=yaw;SynchronizeTruck();position=SidewalkPoint(position);cameraReady=false;var stolen=Trouble.Stolen.ToHashSet();foreach(var v in fleet.Where(v=>stolen.Contains(v.Id)))v.Point=FindRoad(v.Point+new Vector2(100,100));Trouble.Stolen.Clear();InitializeTrouble();Tell("Booked and released. Paid $"+paid+" / outstanding fines $"+Trouble.Fines+". Your truck is nearby.");}
 bool PoliceBlocked(Vector2 point,float heading)=>police.Any(p=>Vector2.DistanceSquared(p.Point,point)<200&&VehiclePhysics.Overlap(point,heading,ActiveSpec,p.Point,p.Yaw,VehicleSpec.For("car")));
 void UpdateTrouble(float dt){incidentCooldown=Math.Max(0,incidentCooldown-dt);Trouble.ReportDelay=Math.Max(0,Trouble.ReportDelay-dt);var target=OutsidePosition;int stars=TroubleRules.Stars(Trouble.Heat);troubleSeen=false;
  foreach(var p in police){if(bodyMotion.TryGetValue(-20000-p.Id,out var physical)&&physical.Hold>0)continue;bool close=interior==0&&Vector2.DistanceSquared(p.Point,target)<130*130&&LineOfSight(p.Point,target);if(close&&driving&&Trouble.Stolen.Contains(activeVehicle)&&stars==0){Crime("Vehicle theft",target,32);stars=TroubleRules.Stars(Trouble.Heat);}bool pursuing=stars>0&&Trouble.ReportDelay<=0&&p.Id<stars;if(pursuing&&close){troubleSeen=true;Trouble.LastX=target.X;Trouble.LastZ=target.Y;}
   p.Repath-=dt;if(p.Repath<=0||p.Step>=p.Route.Count){Vector2 goal;if(pursuing)goal=close?target:new(Trouble.LastX,Trouble.LastZ);else{var links=citySpawnLinks.Where(l=>Vector2.DistanceSquared(carRouter.Nodes[l.From],p.Point)<600*600).ToList();goal=links.Count>0?carRouter.Nodes[links[(p.Id+(int)elapsed/8)%links.Count].To]:FindRoad(target+new Vector2(250,250));}p.Route=carRouter.Route(p.Point,goal);p.Step=1;p.Repath=pursuing?2:8;}
   if(p.Step<p.Route.Count){var q=p.Route[p.Step];var delta=q-p.Point;if(delta.LengthSquared()<4)p.Step++;else{var dir=Vector2.Normalize(delta);p.Yaw=MathF.Atan2(-dir.X,-dir.Y);var next=p.Point+dir*Math.Min(delta.Length(),dt*(pursuing?15:8));if(!VehicleBlocked(next,p.Yaw,-1,VehicleSpec.For("car"))&&!TrafficBlocked(next,p.Yaw,VehicleSpec.For("car")))p.Point=next;}}
   bool wasFoot=p.OnFoot;p.OnFoot=pursuing&&!driving&&Vector2.DistanceSquared(p.Point,target)<50*50;if(p.OnFoot&&!wasFoot)p.Officer=p.Point;if(!p.OnFoot)p.Officer=p.Point;else{var delta=target-p.Officer;if(delta.LengthSquared()>4){var next=p.Officer+Vector2.Normalize(delta)*dt*3.5f;if(!Blocked(next)&&!PedestrianVehicleBlocked(next))p.Officer=next;}if(interior==0&&Vector2.DistanceSquared(p.Officer,target)<100&&LineOfSight(p.Officer,target))troubleSeen=true;}
  }
  if(stars>0&&Trouble.ReportDelay<=0){if(troubleSeen)Trouble.Escape=0;else Trouble.Escape+=dt;if(Trouble.Escape>=35){Trouble.Heat=0;Trouble.Escape=0;Tell("Search called off. Fines, stolen vehicles and damage remain.");}}
  bool caught=stars>0&&Trouble.ReportDelay<=0&&interior==0&&police.Take(stars).Any(p=>Vector2.DistanceSquared(driving?p.Point:p.Officer,target)<(driving?14*14:4*4)&&LineOfSight(p.Point,target));if(caught&&(!driving||Math.Abs(speed)<1)){arrestTimer+=dt;if(arrestTimer>3)Arrest();}else arrestTimer=0;
 }
 void DrawTrouble(MeshBuilder m){foreach(var p in police){if(Vector2.DistanceSquared(p.Point,position)>550*550)continue;var model=VehicleModels.Make(new(){Kind="car",Paint=2});var transform=Matrix.CreateRotationY(p.Yaw)*Matrix.CreateTranslation(p.Point.X,GroundHeight(p.Point),p.Point.Y);foreach(var v in model.Vertices)m.Vertices.Add(new(Vector3.Transform(v.Position,transform),v.Color));float y=GroundHeight(p.Point);bool pursuit=Trouble.Heat>0&&Trouble.ReportDelay<=0&&p.Id<TroubleRules.Stars(Trouble.Heat);bool flash=pursuit&&(int)(elapsed*6)%2==0;m.Box(new(p.Point.X-.65f,y+1.8f,p.Point.Y-.15f),new(p.Point.X,y+2,p.Point.Y+.15f),flash?Color.Red:new(70,20,20));m.Box(new(p.Point.X,y+1.8f,p.Point.Y-.15f),new(p.Point.X+.65f,y+2,p.Point.Y+.15f),pursuit&&!flash?Color.Blue:new(20,20,70));if(p.OnFoot){var q=p.Officer;m.Box(Geo.V3(q-new Vector2(.2f),GroundHeight(q)),Geo.V3(q+new Vector2(.2f),GroundHeight(q)+1.4f),new(36,55,83));m.Box(Geo.V3(q-new Vector2(.16f),GroundHeight(q)+1.4f),Geo.V3(q+new Vector2(.16f),GroundHeight(q)+1.8f),new(207,165,126));}}
  foreach(var damage in Trouble.PropertyDamage){var b=world.Buildings.FirstOrDefault(b=>b.Id==damage.Key);if(b==null||Vector2.DistanceSquared(b.Door,position)>250*250)continue;m.Box(Geo.V3(b.Door-new Vector2(.45f),0),Geo.V3(b.Door+new Vector2(.45f),1),new(55,48,39));}
 }
 void TroubleHud(){if(map||journal||help||dialog)return;int stars=TroubleRules.Stars(Trouble.Heat);if(stars>0){Panel(new(20,205,650,42),new(48,25,29,235));Text("WANTED "+new string('*',stars)+" / "+(Trouble.ReportDelay>0?"REPORT INCOMING":troubleSeen?"IN SIGHT":"SEARCH / "+Math.Max(0,35-Trouble.Escape).ToString("0")+" SEC"),30,216,new(255,174,119),1.3f);}Text("FINES $"+Trouble.Fines+(driving?" / DAMAGE "+ActiveVehicle.Damage.ToString("0")+"%":"")+" / X damage / K repair / B surrender",30,viewH-140,new(232,180,136),1);}
 void TroubleSmoke(){var v=fleet.First(v=>v.Id!=0);position=v.Point;citizens[0].Point=position+new Vector2(3,0);Trouble.Stolen.Clear();Trouble.Heat=0;Trouble.ReportDelay=0;EnterVehicle(v);if(!Trouble.Stolen.Contains(v.Id)||Trouble.Heat<=0||Trouble.ReportDelay<=0)throw new InvalidDataException("Witnessed theft failed");Impact(position,0,12);if(v.Damage<=0||Trouble.Fines<=0)throw new InvalidDataException("Impact consequences failed");Save();float heat=Trouble.Heat;LoadSave();if(Trouble.Heat!=heat||!Trouble.Stolen.Contains(v.Id)||ActiveVehicle.Damage<=0)throw new InvalidDataException("Crime save lost progress");var stopped=traffic.First();stopped.Speed=0;position=stopped.Point;driving=false;TakeTraffic(stopped);if(traffic.Contains(stopped)||!Trouble.Stolen.Contains(activeVehicle)||!fleet.Any(w=>w.Id==activeVehicle))throw new InvalidDataException("Stopped traffic theft failed");Trouble.ReportDelay=0;police[0].Point=FindRoad(position+new Vector2(40,0));UpdateTrouble(.1f);thirdPerson=true;cameraReady=false;Capture("wanted-pursuit");var road=citySpawnLinks.FirstOrDefault(l=>Vector2.Distance(carRouter.Nodes[l.From],carRouter.Nodes[l.To])>100&&!VehicleBlocked(Vector2.Lerp(carRouter.Nodes[l.From],carRouter.Nodes[l.To],.3f),LinkYaw(l),-1,VehicleSpec.For("car"))&&!TrafficBlocked(Vector2.Lerp(carRouter.Nodes[l.From],carRouter.Nodes[l.To],.3f),LinkYaw(l),VehicleSpec.For("car")));if(road==null)throw new InvalidDataException("No police movement test road");police[0].Point=Vector2.Lerp(carRouter.Nodes[road.From],carRouter.Nodes[road.To],.3f);var start=police[0].Point;position=start+Vector2.Normalize(carRouter.Nodes[road.To]-carRouter.Nodes[road.From])*35;driving=false;Trouble.Heat=32;Trouble.LastX=position.X;Trouble.LastZ=position.Y;Trouble.ReportDelay=0;police[0].Route=[];police[0].Repath=0;for(int i=0;i<40;i++)UpdateTrouble(.1f);if(Vector2.Distance(police[0].Point,start)<2)throw new InvalidDataException("Police pursuit did not move");yaw=MathF.Atan2(-(police[0].Point-position).X,-(police[0].Point-position).Y);cameraReady=false;Capture("police-response");Trouble.Heat=32;Trouble.ReportDelay=0;for(int i=0;i<3;i++)police[i].Point=position+new Vector2(3000+i*100,3000);for(int i=0;i<360;i++){foreach(var p in police)p.Repath=100;UpdateTrouble(.1f);}if(Trouble.Heat!=0)throw new InvalidDataException("Escape did not clear wanted state");Trouble.Heat=32;int before=Trouble.Arrests;Arrest();if(Trouble.Heat!=0||Trouble.Arrests!=before+1||Trouble.Stolen.Count!=0||driving)throw new InvalidDataException("Arrest consequence failed");Console.WriteLine("PASS trouble: witnessed theft, impact damage/fines, save/load, pursuit render, escape and arrest.");}
}
